INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob mehr Verantwortung immer zu besseren Ergebnissen führt?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Fähigkeiten ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist entscheidend, wenn ich komplexere Aufgaben übernehme?', 3, '[{"text": "Zeitmanagement", "correct": true, "because": "Balanciert Verantwortung"}, {"text": "Schnelle Hardware", "correct": false, "because": "Sekundär"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren unterstützen mich bei anspruchsvolleren IT-Projekten?', 5, '[{"text": "Weiterbildung", "correct": true, "because": "Erhöht Kompetenz"}, {"text": "Autonomie", "correct": true, "because": "Fördert Eigenverantwortung"}, {"text": "Hoher Speicherplatz", "correct": false, "because": "Nur technisch relevant"}, {"text": "Viele Monitore", "correct": false, "because": "Hilft, aber nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Komplexere Aufgaben fördern Kreativität. b) Sie erfordern immer mehr Zeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeit hängt von Effizienz ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich mehr Verantwortung für ein Netzwerk übernehme?', 4, '[{"text": "Sicherheitsrichtlinien", "correct": false, "because": "Zentral für Schutz"}, {"text": "Dokumentation", "correct": false, "because": "Wichtig für Nachvollziehbarkeit"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass komplexere Aufgaben automatisch mehr Spaß machen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Interessen ab"}, {"text": "Ja", "correct": false, "because": "Nicht für jeden zutreffend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fähigkeit ist für die Leitung eines IT-Projekts entscheidend?', 3, '[{"text": "Entscheidungsfähigkeit", "correct": true, "because": "Fördert klare Richtungen"}, {"text": "Schnellere CPU", "correct": false, "because": "Hardware-spezifisch"}, {"text": "Großer Cache", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen helfen mir, anspruchsvolle IT-Aufgaben zu meistern?', 5, '[{"text": "Priorisierung", "correct": true, "because": "Fokussiert wichtige Aufgaben"}, {"text": "Feedback einholen", "correct": true, "because": "Verbessert Ergebnisse"}, {"text": "Hohe Bildschirmhelligkeit", "correct": false, "because": "Irrelevant"}, {"text": "Viele Kaffeepausen", "correct": false, "because": "Lenkt ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Mehr Verantwortung erfordert bessere Planung. b) Sie führt immer zu Stress.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Stress ist vermeidbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich ein Backup-System verwalte?', 4, '[{"text": "Teststrategie", "correct": false, "because": "Sichert Wiederherstellung"}, {"text": "Zeitplan", "correct": false, "because": "Wichtig für Regelmäßigkeit"}, {"text": "Schreibtischordnung", "correct": true, "because": "Irrelevant für Backup"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert mehr Eigenverantwortung immer die Effizienz?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Kompetenz ab"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool unterstützt mich bei komplexeren Netzwerkaufgaben?', 3, '[{"text": "Monitoring-Software", "correct": true, "because": "Erkennt Probleme früh"}, {"text": "Texteditor", "correct": false, "because": "Nur für Skripte"}, {"text": "Grafikprogramm", "correct": false, "because": "Nicht netzwerkrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass komplexere Aufgaben immer bessere Hardware brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Oft reicht Optimierung"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte verbessern meine Arbeit an einem Server-Projekt?', 5, '[{"text": "Dokumentation", "correct": true, "because": "Erleichtert Wartung"}, {"text": "Testphasen", "correct": true, "because": "Sichert Stabilität"}, {"text": "Schnelle Internetleitung", "correct": false, "because": "Nur teilweise relevant"}, {"text": "Bunte Kabel", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Firewall eigenständig konfiguriere?', 4, '[{"text": "Regelgenauigkeit", "correct": true, "because": "Sichert Schutz"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Qualität zählt"}, {"text": "Optisches Design", "correct": false, "because": "Nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob mehr Verantwortung immer Schulungen voraussetzt?', 2, '[{"text": "Nein", "correct": true, "because": "Erfahrung kann reichen"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen sind korrekt? a) Komplexe Aufgaben fördern Lernprozesse. b) Sie erfordern immer ein Team.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einzelarbeit möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Datenbank eigenständig verwalte?', 4, '[{"text": "Zugriffskontrollen", "correct": false, "because": "Sichern Daten"}, {"text": "Backup-Pläne", "correct": false, "because": "Schützen vor Verlust"}, {"text": "Raumdekoration", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist mehr Komplexität immer mit mehr Fehlern verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Planung reduziert Fehler"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fähigkeit hilft mir, ein eigenständiges IT-Projekt zu leiten?', 3, '[{"text": "Problemlösung", "correct": true, "because": "Tackelt Herausforderungen"}, {"text": "Schnelles Tippen", "correct": false, "because": "Nur unterstützend"}, {"text": "Farbcodierung", "correct": false, "because": "Nicht zentral"}]');
